<?php
require_once __DIR__.'/config/bootstrap.php';
$id=(int)($_GET['id']??0);
$stmt=$pdo->prepare("SELECT s.*,u.name AS author,u.role AS author_role,c.name AS category_name FROM submissions s JOIN users u ON u.id=s.user_id LEFT JOIN categories c ON c.id=s.category_id WHERE s.id=?");
$stmt->execute([$id]); $item=$stmt->fetch();
if(!$item){http_response_code(404); render_header('Not found'); echo '<main id="main" class="container section"><h1>Resource not found</h1><p>This archive record does not exist.</p></main>'; render_footer(); exit;}
$u=current_user();
$canReview=can_review_submission($item);
$allowed=($item['status']==='approved' && $item['visibility']==='public') || ($u && ((int)$u['id']===(int)$item['user_id'] || is_admin())) || $canReview;
if(!$allowed){http_response_code(403); render_header('Access denied'); echo '<main id="main" class="container section"><div class="denied"><h1>403 · Access denied</h1><p>This resource is private or has not been published. Sign in as the owner or an authorized admin to access it.</p><a class="button button-primary" href="index.php">Back to public archive</a></div></main>'; render_footer(); exit;}
render_header('Resource details');
$ext=strtolower(pathinfo((string)$item['original_name'],PATHINFO_EXTENSION));
?>
<main id="main" class="container section detail-page"><a class="back-link" href="<?=is_admin()||($u && (int)$u['id']===(int)$item['user_id'])?'dashboard.php':($canReview?'dashboard.php#faculty-review-queue':'index.php')?>">← Back</a><div class="detail-layout"><article class="detail-main"><div class="resource-top"><span class="file-chip"><?=strtoupper(e($item['resource_type']==='link'?'LINK':($ext?:'FILE')))?></span><span class="status status-<?=e($item['status'])?>" id="review-status-badge"><?=e(status_label($item['status']))?></span></div><h1><?=e($item['title'])?></h1><p class="detail-description"><?=nl2br(e($item['description']))?></p>
<?php if($item['resource_type']==='link'): ?><div class="preview-panel" data-animation="preview"><div class="preview-icon">↗</div><h2>External web resource</h2><p>The original resource is hosted on another website.</p><?php $domain=link_domain($item['external_url']); if($domain): ?><p>Destination: <strong><?=e($domain)?></strong></p><?php endif; ?><a class="button button-primary" href="<?=e($item['external_url'])?>" target="_blank" rel="noopener noreferrer">Open external link ↗</a></div>
<?php else: ?><div class="preview-panel" data-animation="preview"><?php $url='api/download.php?id='.(int)$item['id'].'&inline=1'; if($ext==='pdf'): ?><iframe class="pdf-frame" title="PDF preview" src="<?=e($url)?>"></iframe><?php elseif(in_array($ext,['mp4','webm'],true)): ?><video controls preload="metadata" class="media-player"><source src="<?=e($url)?>" type="<?=e($item['mime_type'])?>">Your browser does not support video playback.</video><?php elseif(in_array($ext,['mp3','wav','m4a'],true)): ?><div class="preview-icon">♫</div><audio controls preload="metadata" class="audio-player"><source src="<?=e($url)?>" type="<?=e($item['mime_type'])?>">Your browser does not support audio playback.</audio><?php elseif(in_array($ext,['jpg','jpeg','png','gif','webp'],true)): ?><img class="image-preview" src="<?=e($url)?>" alt="<?=e($item['title'])?>"><?php else: ?><div class="preview-icon">▤</div><h2>Preview not available</h2><p>This file type can be downloaded safely.</p><?php endif; ?><a class="button button-primary download-button" href="api/download.php?id=<?=(int)$item['id']?>">Download resource ↓</a></div><?php endif; ?>
<?php if($u): ?><form action="api/favorites.php" method="post" class="favorite-form" data-favorite-form><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="submission_id" value="<?=(int)$item['id']?>"><button class="button button-outline" type="submit" data-favorite-toggle><?=is_favorited($pdo,(int)$u['id'],(int)$item['id'])?'★ Favorited, remove from favorites':'☆ Add to favorites'?></button></form><?php endif; ?>
<?php if($canReview): ?><section class="review-panel" data-review-item><h2><?=is_admin()?'Admin review':'Faculty review'?></h2><?php if(!is_admin()): ?><p class="muted">Faculty reviewers can review public student submissions. Private records remain restricted to their owner and administrators.</p><?php endif; ?><form action="api/review.php" method="post" class="stack-form" data-review-form><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="submission_id" value="<?=(int)$item['id']?>"><label>Feedback <small>Required when rejecting or returning, so the owner knows what to fix.</small><textarea name="feedback" rows="2" maxlength="1500" placeholder="Feedback for the submitter"><?=e($item['feedback'])?></textarea></label><div class="review-actions"><button class="button button-primary" name="decision" value="approved">Approve / Publish</button><button class="button button-outline" name="decision" value="returned">Return for revision</button><button class="button button-danger" name="decision" value="rejected">Reject</button></div><p class="review-status" id="review-status" aria-live="polite"></p></form></section><?php endif; ?>
<?php if(can_edit_submission($item)||can_delete_submission($item)): ?><section class="review-panel detail-actions"><h2>Manage this record</h2><div class="review-actions"><?php if(can_edit_submission($item)): ?><a class="button button-outline" href="edit.php?id=<?=(int)$item['id']?>">Edit record</a><?php endif; ?><?php if(can_delete_submission($item)): ?><form class="inline-form" action="api/delete.php" method="post" onsubmit="return confirm('Delete this record? This cannot be undone.');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="submission_id" value="<?=(int)$item['id']?>"><button class="button button-danger" type="submit">Delete record</button></form><?php endif; ?></div></section><?php endif; ?>
</article><aside class="detail-side"><div class="side-card"><h2>Resource details</h2><dl><dt>Submitted by</dt><dd><?=e($item['author'])?></dd><dt>Category</dt><dd><?=e($item['category_name']??'General')?></dd><dt>Academic year</dt><dd><?=e($item['academic_year']?:'Not specified')?></dd><dt>Visibility</dt><dd><?=e(ucfirst($item['visibility']))?></dd><dt>Downloads</dt><dd><?=(int)($item['download_count']??0)?></dd><dt>Submitted</dt><dd><?=e(date('F j, Y',strtotime($item['created_at'])))?></dd><?php if($item['resource_type']==='link' && link_domain($item['external_url'])): ?><dt>Destination</dt><dd><?=e(link_domain($item['external_url']))?></dd><?php endif; ?><?php if($item['original_name']): ?><dt>Original file</dt><dd><?=e($item['original_name'])?></dd><?php endif; ?></dl></div></aside></div></main>
<?php render_footer(); ?>
